"""Руководства по пяти экранам управления армией Frontier International."""
from html import escape

from combat_guides import table


def screen_guides(page, register, illustration):
    screens = [
        ("army-plan", "План, приказы и лечение", "frontier-plan",
         "В «Плане» слева показаны ОЗ и цена лечения отрядов, справа — их приказы, стили, доступные навыки и боевая награда.",
         """<p>В «Плане» можно вылечить бойцов, назначить отрядам приказы и посмотреть, сколько еды или магии уйдёт на следующий бой. На снимке у первого отряда 485 ОЗ и нулевая цена лечения. Если он вступит в бой, из запаса армии спишут 318 магии.</p>
<h2>Лечение одного бойца и всей армии</h2>
<p>Щелчок по портрету лечит бойца, по номеру слева — весь отряд. Кнопка «Все отряды» охватывает тех, кто стоит в строю. «Вся армия» захватывает и резерв. Цена равна сумме недостающих ОЗ, умноженных на цену лечения каждого бойца.</p>
<p>У Гарма восстановление одной единицы здоровья стоит 5 золотых. Если у него осталось 70 из 100 ОЗ, полное лечение обойдётся в 150 золотых. При 100 золотых игра восстановит 20 ОЗ, и Гарм останется на 90. Если сразу отправить его в бой с 70 ОЗ, лечебные навыки восстановят здоровье максимум до 70. Бойцы, которые не участвовали в бою, восстанавливают часть ОЗ в конце хода.</p>
<h2>Приказ отряду</h2>""" + table(("Статус", "Когда отряд вступает в автоматическую стычку"), [
             ("Атака", "После основного боя с оставшимся противником на атакованной территории."),
             ("Защита", "При вторжении противника на землю Локи."),
             ("Отдых", "Пропускает автоматические стычки."),
         ]) + """
<p>Обычная стычка длится один раунд. Если запасному отряду не хватит здоровья на следующий выход, статус можно поменять у его номера. Кнопки под списком меняют приказ сразу всей армии.</p>
<h2>Стиль и тактика</h2>
<p>Стиль задаёт боевую прибавку. «Натиск» повышает атаку, «Оборона» — защиту, «Скорость» — скорость и боевой дух. За каждые полные 20 единиц квадратного корня из опыта армии основные прибавки увеличиваются на 1. Боевой дух в стиле «Скорость» использует делитель 60.</p>"""
         + table(("Опыт армии", "Натиск · атака", "Оборона · защита", "Скорость · скорость и дух"), [
             ("0", "+3", "+5", "+4 и +1"),
             ("3 600", "+6", "+8", "+7 и +2"),
         ]) + """
<p>Кнопка «Навыки» в столбце «Тактика» открывает список приёмов командиров. Рядом с названием приёма указан уровень силы, который нужен для его применения. <a href="tactical.html">Расчёт тактического урона и лечения →</a></p>""",
         "Приказы отрядам, отдых, золото, цена лечения, здоровье, боевой стиль"),
        ("recruitment", "Наём бойцов и ковка медальонов", "frontier-hire",
         "В окне найма запас медальонов слева, цена и две ячейки титулов в центре, доступные бойцы справа.",
         """<p>Один наём расходует действие хода, обязательные медальоны и указанное количество еды или магии. После выбора бойца красные числа показывают, сколько медальонов останется после найма. Звезда на портрете означает, что этот боец уже принят в армию и доступен в «Отрядах».</p>
<h2>Что нужно орку-стражнику</h2>
<p>Для найма орка-стражника нужны медальон адского зверя и медальон стража. У бойца 80 базовых ОЗ, 13 защиты и «Защитная тактика» 4. В открытой карточке отдельно видна текущая цена найма. Она меняется даже у одного бойца, когда меняется луна или время суток.</p>
<h2>Когда выгоднее нанимать</h2>
<p>Игра складывает совместимость стихии с луной и поправку за время суток, затем ограничивает итог от 0 до 4. У орка-стражника стихия земли и бонус +2 за ночной наём. Луна земли даёт ему +3, луна ветра −2. Без титулов базовая цена равна 18 магии.</p>"""
         + table(("Фаза и время", "Оценка найма", "Цена, магия", "Начальная защита"), [
             ("Ветер, ночь", "0", "54", "5"),
             ("Земля, день", "3", "21", "15"),
             ("Земля, ночь", "4", "18", "17"),
         ]) + """
<p>При оценке 0 из атаки, защиты, скорости и духа вычитается по 8. При оценке 4 к первым трём характеристикам прибавляется по 4, к духу — 1. После всех поправок характеристики ограничены снизу единицей. Дробную часть цены игра отбрасывает.</p>
<h2>Дополнительный медальон и титул</h2>
<p>Титул выбирается до нажатия «Нанять». Знак &lt; указывает на левую ячейку, &gt; — на правую, &lt;&gt; разрешает обе. Доступные медальоны зависят от ранга роста бойца. Орку-стражнику с титулом «Отважный» понадобятся два медальона стража — один по рецепту и ещё один за титул.</p>
<p>«Отважный» даёт +4 к атаке, +3 к боевому духу и «Тактику боевого духа» 1. В ночь земли такой орк обойдётся в 21 магию вместо 18. Титул увеличивает ранг для расчёта цены на 3, а сам ранг роста бойца остаётся прежним.</p>
<h2>Ковка, добыча и увольнение</h2>
<p>За победы над отрядами можно получить медальоны. Для ковки выберите вид в списке слева и нажмите «Ковать». Например, медальон адского зверя стоит 250 ресурсов и один материал для медальона. Открытие новых видов расширяет набор доступных бойцов. При увольнении предметы возвращаются на склад, а потраченные медальоны остаются списанными.</p>
<p><a href="formation.html">Куда поставить нового бойца →</a></p>""",
         "Медальоны, титулы, ковка, цена найма, орк-стражник, фазы луны"),
        ("formation", "Отряды и построение", "frontier-formation",
         "Слева десять отрядов по шесть ячеек. Справа списки рядовых и командиров. В первом отряде на снимке пять бойцов, шестая позиция свободна.",
         """<p>Откройте «Отряды», выберите номер и перетащите бойцов в ячейки слева. Игра позволяет собрать до десяти отрядов по шесть бойцов. Во вкладке «Командиры» находятся герои с тактическими навыками. Если в одном отряде несколько командиров, он получает доступ к их приёмам.</p>
<h2>Передний ряд и прикрытие</h2>
<p>Первые три позиции составляют передний ряд, позиции с четвёртой по шестую — задний. Фена с «Защитной тактикой» на первой позиции перехватывает обычные одиночные удары, направленные по союзникам за ней. На второй она прикроет позиции с третьей по шестую, а первая останется открыта. «Атака в обход» и дальний удар днём обходят прикрытие. Ночью дальний удар без навыка ночного боя может снова попасть в стража.</p>
<h2>Что даёт четвёртый боец</h2>
<p>Групповая прибавка от «Защитной тактики» зависит от числа живых бойцов. Фена даёт отряду +15 к защите, пока живы хотя бы четверо. При трёх эта прибавка исчезает. Перехват ударов вычисляется отдельно, и Фена всё ещё может прикрывать союзников. Тактика атаки, скорости и боевого духа использует тот же порог из четырёх живых бойцов.</p>
<h2>Пять бойцов на снимке</h2>""" + table(("Боец", "Базовые ОЗ", "Что даёт отряду"), [
             ("Фена", "95", "Защитная тактика 15, магический барьер 60, лечение бойцов всех типов 10."),
             ("Локи", "105", "Пробивает защиту расколом шлема 50 и даёт доступ к своим тактическим приёмам."),
             ("Лупольд-копейщица", "95", "Тактика атаки 15 и сквозная атака."),
             ("Гарм", "100", "Дальняя атака, тактика засады 12 и повышенный шанс крита 25."),
             ("Кобольд-инженер", "90", "Групповое лечение 8 и возведение укреплений 75."),
         ]) + """
<p>Всего у отряда 485 ОЗ до роста и боевых поправок. От численности зависит и устойчивость поддержки: при двух потерях из пяти в строю останутся трое и «Защитная тактика» Фены перестанет давать +15. Шестой боец даёт запас на ещё одну потерю.</p>
<p>Гарм даёт 12 очков засады. Днём против отряда без бдительности это сдвиг на одну позицию. Ночью добавляется 9 очков, и результат 21 сдвигает строй на две. Если у противника 4 бдительности, остаётся 17, то есть одна позиция. <a href="equipment.html">Как добавить бдительность снаряжением →</a></p>""",
         "Построение, состав, страж, передний ряд, задний ряд, командиры, Фена, Гарм, засада"),
        ("equipment", "Снаряжение и торговля рудой", "frontier-equipment",
         "В «Снаряж.» слева находятся магазин и предметы, справа бойцы и два значка доступных им типов экипировки.",
         """<p>Выберите бойца справа. Значки под его портретом показывают, какие виды предметов ему подходят. Перетащите предмет в подсвеченную ячейку. Правый щелчок снимает предмет и возвращает его на склад. Два предмета одного типа надеть нельзя.</p>
<h2>Что надеть на орка-стражника</h2>
<p>Орк-стражник носит одноручное оружие и щит. Стартовый кинжал подойдёт в первую ячейку, баклер — во вторую. Вместе они стоят 200 золотых и дают +1 к атаке, +2 к защите и +3 к скорости до прочих поправок.</p>"""
         + table(("Предмет", "Цена", "Прибавки", "Навык"), [
             ("Кинжал", "100", "+1 атака, +2 скорость", "Парирование 2"),
             ("Баклер", "100", "+2 защита, +1 скорость", "Уклонение 2"),
             ("Каплевидный щит", "800", "+10 защита, −2 скорость", "Парирование 8, снятие ослаблений"),
             ("Кожаный доспех", "400", "+4 защита, +2 скорость", "Бдительность 4"),
         ]) + """
<p>Кожаный доспех относится к другой категории. Его можно дать, например, Локи. Бдительность 4 уменьшает итог засады против всего его отряда на четыре очка. Это меняет результат, если противник набрал от 10 до 13 очков сверх прочей бдительности.</p>
<h2>Как открыть редкость 3 и выше</h2>
<p>Предметы редкости 1 и 2 продаются сразу. Для покупки снаряжения редкости 3 и выше нужен запас руды того же уровня. Проданная руда поступает в запас магазина. Он списывает 10 единиц на каждый такой предмет. Цена в золоте при этом сохраняется.</p>
<p>Для одного каплевидного щита нужны 800 золотых и 10 единиц материала редкости 3. Продажа десяти единиц серебряной руды пополнит запас на 10 и принесёт 3 000 золотых. Руда типа «Материал» по умолчанию уходит в автопродажу после боя. Положение переключателя «Автопродажа руды» видно под магазином.</p>
<p>Кнопка количества позволяет купить или продать 1, 4 или 10 предметов за раз. При продаже предмета магазин платит половину его цены. За снятый баклер можно получить 50 золотых.</p>""",
         "Экипировка, оружие, щит, броня, руда, автопродажа, закупка, редкость"),
        ("call-events", "Вызов, общение и симпатия", "frontier-call",
         "В начале кампании в «Вызове» доступна Фена. Симпатия показана над полосой общения, Захват и Власть — внизу слева.",
         """<p>На экране «Вызов» можно включить общение с доступной героиней. После завершения хода полоса растёт. Когда появляется кнопка встречи, нажатие на неё запускает сцену и тратит действие. Уже открытая, но ещё не просмотренная встреча приостанавливает начисление очков для этой героини.</p>
<h2>Сколько очков за ход</h2>
<p>Общение и воздействие на богиню настраиваются независимо. В разных версиях игры второй режим называется «Дрессура» или «Осквернить». У Фены и трёх демонических сестёр на этом экране растёт только общение. У богинь можно включить оба режима.</p>"""
         + table(("Включено", "За один ход", "За четыре хода без ожидающей встречи"), [
             ("Только общение", "+2 общения", "8 общения"),
             ("Только воздействие", "+2 воздействия", "8 воздействия"),
             ("Оба режима", "+1 к каждой полосе", "4 общения и 4 воздействия"),
         ]) + """
<h2>Что решает симпатия</h2>
<p>Очки общения открывают встречи. Симпатия меняется в сценах и от ответов Локи. По ней игра проверяет условия личных эпилогов. Например, бонусная сцена Фены в Порядке требует 9 симпатии. Следующая сцена после титров требует 12 и прохождения предыдущей.</p>
<h2>Захват и Власть</h2>
<p>Две полосы слева внизу относятся ко всей кампании. За некоторые ответы растёт Захват или Власть. При Захвате от 30 игра направляет в Хаос. Значения Власти от 20 и Захвата от 20 до 29 включительно дают выбрать одну из трёх веток на развилке. Условия остальных вариантов и полный разбор эпилогов собраны в <a href="walkthrough.html">прохождении со спойлерами</a>.</p>""",
         "Фена, встреча с героиней, общение, симпатия, Захват, Власть, эпилог"),
    ]
    for slug, title, image, caption, body, keywords in screens:
        page(slug + ".html", title, "mechanics.html",
             '<div class="wrap guide-layout"><article><div class="crumb"><a href="mechanics.html">Механика Frontier</a></div>'
             f'<h1>{escape(title)}</h1>{illustration("scenes/" + image, caption)}{body}</article></div>')
        register(title, slug + ".html", "Механика Frontier", keywords)
    return '<ul class="reading-list">' + "".join(
        f'<li><a href="{slug}.html">{escape(title)}</a></li>' for slug, title, *_ in screens
    ) + '</ul>'
